use std::fs::File;
use std::io::Read;
pub const VTX_BUF_LEN: usize = 4096;
pub const VTX_MAX_ID: u16 = 1024;
pub enum VtxErr { Io, IdTooLarge }
pub fn vtx_read_packet_id(f: &mut File) -> Result<u16, VtxErr> {
    let mut buf = [0u8; VTX_BUF_LEN];
    f.read_exact(&mut buf[..2]).map_err(|_| VtxErr::Io)?;
    let id = u16::from_be_bytes([buf[0], buf[1]]);
    if id > VTX_MAX_ID { return Err(VtxErr::IdTooLarge); }
    Ok(id)
}
